  const click = async (sel) => {
    for (let i = 0; i < 40; i++) {
      if ((await ev(`!!${q(sel)}`)) === true) break;
      await sleep(150);
    }
    const ok = await ev(`(function(){var el=${q(sel)};if(!el||el.disabled)return 'MISSING:'+${JSON.stringify(sel)};el.click();return 'ok';})()`);
